const payload = $json.body ?? $json;
const stories = Array.isArray(payload.stories) ? payload.stories : [];
const clean = (value) => String(value ?? '').replace(/[\r\n]+/g, ' ').replace(/\s+/g, ' ').trim();
const ranked = stories
  .filter((story) => story && clean(story.title))
  .sort((a, b) => Number(b.score ?? 0) - Number(a.score ?? 0))
  .slice(0, 8);

const stamp = new Intl.DateTimeFormat('en-IN', {
  timeZone: 'Asia/Kolkata',
  dateStyle: 'medium',
  timeStyle: 'short',
}).format(new Date());

const lines = [
  `AI NEWS SHORTLIST — ${stamp} IST`,
  `Mode: ${clean(payload.mode || 'unknown')} | Fetched: ${Number(payload.fetched ?? stories.length)} | Stored: ${Number(payload.stored ?? stories.length)}`,
  '',
];

ranked.forEach((story, index) => {
  lines.push(`${index + 1}. ${clean(story.title)}`);
  lines.push(`Source: ${clean(story.source || 'Unknown')}`);
  if (clean(story.summary)) lines.push(`Summary: ${clean(story.summary)}`);
  if (clean(story.why_it_matters)) lines.push(`Why it may matter: ${clean(story.why_it_matters)}`);
  if (clean(story.url)) lines.push(clean(story.url));
  lines.push('');
});

if (ranked.length === 0) {
  lines.push('No stories were returned. Inspect the refresh execution and API errors.');
}

const errors = Array.isArray(payload.errors) ? payload.errors.map(clean).filter(Boolean) : [];
if (errors.length) {
  lines.push('Refresh warnings:');
  errors.forEach((error) => lines.push(`- ${error}`));
}

const telegramEnabled = String($env.TELEGRAM_ENABLED || 'false').toLowerCase() === 'true';
const telegramConfigured = Boolean($env.TELEGRAM_CHAT_ID);

return [{
  json: {
    generated_at: new Date().toISOString(),
    mode: payload.mode || 'unknown',
    story_count: ranked.length,
    stories: ranked,
    digest: lines.join('\n').trim(),
    telegram_enabled: telegramEnabled && telegramConfigured,
    telegram_status: telegramEnabled
      ? (telegramConfigured ? 'enabled; Telegram credential must also be selected on the delivery node' : 'requested but missing TELEGRAM_CHAT_ID')
      : 'disabled by TELEGRAM_ENABLED=false',
  },
}];

const limit = 3900;
const paragraphs = String($json.digest || '').split(/\n\n+/);
const chunks = [];
let current = '';
for (const paragraph of paragraphs) {
  if (paragraph.length > limit) {
    if (current) chunks.push(current);
    for (let offset = 0; offset < paragraph.length; offset += limit) chunks.push(paragraph.slice(offset, offset + limit));
    current = '';
    continue;
  }
  const candidate = current ? `${current}\n\n${paragraph}` : paragraph;
  if (candidate.length > limit) {
    chunks.push(current);
    current = paragraph;
  } else {
    current = candidate;
  }
}
if (current) chunks.push(current);
return chunks.map((telegram_text, index) => ({
  json: { ...$json, telegram_text, telegram_chunk: index + 1, telegram_chunk_count: chunks.length },
}));
